selection_review=[
 {'pages':[3,4,16],'wording':'any five / any three questions','classification':'exam-level-selection','reason':'All ten questions retained for practice.'},
 {'pages':[6],'wording':'two other points','classification':'open-answer','reason':'An infinite circle, not a finite candidate selection pool. All seven scheme examples retained in one response.'},
 {'pages':[24],'wording':'One of the numbers / Tick one box only','classification':'single-response-choice','reason':'One correlation-choice card with all four printed values and justification.'},
 {'pages':[27],'wording':'pick 3 forwards','classification':'counting-scenario','reason':'The team selection is problem data; it does not instruct the student to omit tasks.'},
]
def classify(c):
 t=c['context'].lower()
 if 'questions' in t and 'any' in t:return ('exam-level-selection','All ten questions retained.')
 if 'one of henryk' in t or 'one of his fields' in t:return ('scenario-context','One illustrated field is the compulsory problem context.')
 if 'otherwise' in t:return ('method-choice','Alternative methods for one required answer.')
 if 'one of the numbers' in t or 'tick one' in t or 'which one' in t:return ('single-response-choice','All four correlation choices and justification retained in one card.')
 if 'either 7' in t:return ('scenario-outcomes','All scoring outcomes are probability data in a single required task.')
 return None
if __name__=='__main__':p.write(selection_review,classify)
